
import React, { useState } from 'react';
import { Studente, StudentHistoryRecord } from '../types';
import { TabGroup } from './M3Components';

interface StudentTransferModalProps {
    student: Studente;
    userClasses: string[];
    onClose: () => void;
    onSave: (student: Studente) => void;
    currentSchoolYear: string;
}

const StudentTransferModal: React.FC<StudentTransferModalProps> = ({ student, userClasses, onClose, onSave, currentSchoolYear }) => {
    const [mode, setMode] = useState<'change_class' | 'transfer_out'>('change_class');
    const [newClass, setNewClass] = useState(student.classe);
    const [outcome, setOutcome] = useState<'Trasferito' | 'Ritirato'>('Trasferito');
    
    // We allow user to create a new class on the fly if needed
    const [isCustomClass, setIsCustomClass] = useState(false);
    const [customClass, setCustomClass] = useState('');

    const handleSave = () => {
        let updatedStudent = { ...student };
        const currentDate = new Date().toISOString().split('T')[0];

        if (mode === 'change_class') {
            const targetClass = isCustomClass ? customClass.toUpperCase() : newClass;
            if (!targetClass) {
                alert("Seleziona o inserisci la nuova classe.");
                return;
            }
            
            // Create a history record for the partial year in the old class
            const historyRecord: StudentHistoryRecord = {
                year: currentSchoolYear,
                classe: student.classe,
                averageGrade: '-', // Grade calculation would require props drilling, keep it simple for now or calc if available
                absencesPercentage: 0,
                finalOutcome: 'Trasferito', // Internal transfer
                competencySummary: [{ name: 'Cambio Classe', level: `Passaggio alla ${targetClass} il ${currentDate}` }]
            };
            
            updatedStudent.classe = targetClass;
            updatedStudent.history = [...(student.history || []), historyRecord];

        } else {
            // Archive student
            const historyRecord: StudentHistoryRecord = {
                year: currentSchoolYear,
                classe: student.classe,
                averageGrade: '-',
                absencesPercentage: 0,
                finalOutcome: outcome,
                competencySummary: [{ name: 'Uscita', level: `Data: ${currentDate}` }]
            };

            updatedStudent.isArchived = true;
            updatedStudent.archiveYear = currentSchoolYear;
            updatedStudent.history = [...(student.history || []), historyRecord];
        }

        onSave(updatedStudent);
        onClose();
    };

    return (
        <div className="dialog-backdrop">
            <div className="dialog-container w-full max-w-md">
                <div className="dialog-header">
                    <h2 className="m3-headline-medium">Mobilità Studente</h2>
                    <button onClick={onClose} className="icon-button rounded-lg hover:shadow-md transition-all">
                        <span className="material-symbols-outlined">close</span>
                    </button>
                </div>
                
                <div className="dialog-content space-y-6">
                    <p className="m3-body-medium text-on-surface-variant">
                        Gestisci lo spostamento di <strong>{student.cognome} {student.nome}</strong>.
                    </p>

                    <TabGroup
                        tabs={[
                            { id: 'change_class', label: 'Cambio Classe' },
                            { id: 'transfer_out', label: 'Trasferimento / Ritiro' }
                        ]}
                        activeTab={mode}
                        onTabChange={(id) => setMode(id as 'change_class' | 'transfer_out')}
                        variant="secondary"
                        className="w-full"
                    />

                    {mode === 'change_class' ? (
                        <div className="bg-surface-container p-4 rounded-xl border border-outline-variant">
                            <h3 className="m3-label-large mb-2 text-primary">Nuova Destinazione</h3>
                            
                            {!isCustomClass ? (
                                <div className="space-y-3">
                                    <select 
                                        id="new-class-select" // FIX: Add ID
                                        value={newClass} 
                                        onChange={(e) => setNewClass(e.target.value)} 
                                        className="form-select w-full rounded-lg"
                                    >
                                        {userClasses.map(c => <option key={c} value={c}>{c}</option>)}
                                    </select>
                                    <button onClick={() => setIsCustomClass(true)} className="button button-text !h-auto !py-1 text-xs rounded-lg hover:shadow-md transition-all">
                                        La classe non è in elenco?
                                    </button>
                                </div>
                            ) : (
                                <div className="space-y-3">
                                    <input 
                                        id="custom-class-input" // FIX: Add ID
                                        type="text" 
                                        value={customClass} 
                                        onChange={(e) => setCustomClass(e.target.value)} 
                                        className="form-input w-full uppercase rounded-lg"
                                        placeholder="Es. 1C"
                                        autoFocus
                                    />
                                    <button onClick={() => setIsCustomClass(false)} className="button button-text !h-auto !py-1 text-xs rounded-lg hover:shadow-md transition-all">
                                        Torna all'elenco
                                    </button>
                                </div>
                            )}
                            
                            <p className="mt-4 text-xs text-on-surface-variant">
                                Lo studente verrà spostato nella nuova classe. I dati pregressi (voti, note) rimarranno visibili nel profilo.
                            </p>
                        </div>
                    ) : (
                        <div className="bg-error-container text-on-error-container p-4 rounded-xl">
                            <h3 className="m3-label-large mb-2">Archiviazione (Uscita)</h3>
                            <div className="flex flex-col gap-2">
                                <label htmlFor="outcome-trasferito" className="flex items-center gap-2 cursor-pointer"> {/* FIX: Add htmlFor */}
                                    <input 
                                        id="outcome-trasferito" // FIX: Add ID
                                        type="radio" 
                                        name="outcome" 
                                        checked={outcome === 'Trasferito'} 
                                        onChange={() => setOutcome('Trasferito')}
                                        className="accent-error"
                                    />
                                    <span>Trasferito ad altra scuola</span>
                                </label>
                                <label htmlFor="outcome-ritirato" className="flex items-center gap-2 cursor-pointer"> {/* FIX: Add htmlFor */}
                                    <input 
                                        id="outcome-ritirato" // FIX: Add ID
                                        type="radio" 
                                        name="outcome" 
                                        checked={outcome === 'Ritirato'} 
                                        onChange={() => setOutcome('Ritirato')}
                                        className="accent-error"
                                    />
                                    <span>Ritirato dagli studi</span>
                                </label>
                            </div>
                            <p className="mt-4 text-xs opacity-80">
                                Lo studente verrà rimosso dagli elenchi attivi ma i suoi dati saranno conservati nell'archivio storico.
                            </p>
                        </div>
                    )}
                </div>

                <div className="dialog-footer">
                    <button onClick={onClose} className="button button-text rounded-lg hover:shadow-md transition-all">Annulla</button>
                    <button onClick={handleSave} className={`button button-filled rounded-lg hover:shadow-md transition-all ${mode === 'transfer_out' ? 'bg-error text-on-error' : ''}`}>
                        {mode === 'change_class' ? 'Sposta Studente' : 'Archivia Studente'}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default StudentTransferModal;
