import React, { useState, useEffect } from 'react';
import { Studente } from '../types';
import { TextField, SelectField } from './M3Components';

interface AddStudentModalProps {
    studentToEdit?: Studente;
    userClasses: string[];
    onClose: () => void;
    onSave: (student: Studente) => void;
}

const AddStudentModal: React.FC<AddStudentModalProps> = ({ studentToEdit, userClasses, onClose, onSave }) => {
    const [formData, setFormData] = useState({
        cognome: '',
        nome: '',
        classe: userClasses[0] || ''
    });

    useEffect(() => {
        if (studentToEdit) {
            setFormData({
                cognome: studentToEdit.cognome,
                nome: studentToEdit.nome,
                classe: studentToEdit.classe,
            });
        }
    }, [studentToEdit]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData.cognome || !formData.nome || !formData.classe) {
            alert("Per favore, compila tutti i campi.");
            return;
        }
        const studentData: Studente = {
            id: studentToEdit?.id || `stud-${Date.now()}`,
            ...formData
        };
        onSave(studentData);
        onClose();
    };

    return (
        <div className="dialog-backdrop">
            <form onSubmit={handleSubmit} className="dialog-container w-full max-w-lg">
                <div className="dialog-header">
                    <h2 className="m3-headline-medium font-black">{studentToEdit ? 'Modifica Studente' : 'Aggiungi Studente'}</h2>
                    <button type="button" onClick={onClose} className="icon-button rounded-lg hover:shadow-md transition-all">
                        <span className="material-symbols-outlined">close</span>
                    </button>
                </div>
                <div className="dialog-content space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <TextField 
                            id="student-cognome-input" // FIX: Add ID
                            name="cognome" // FIX: Add name
                            label="Cognome" 
                            value={formData.cognome} 
                            onChange={e => setFormData({...formData, cognome: e.target.value})} 
                            placeholder="Es. Rossi" 
                            required 
                        />
                        <TextField 
                            id="student-nome-input" // FIX: Add ID
                            name="nome" // FIX: Add name
                            label="Nome" 
                            value={formData.nome} 
                            onChange={e => setFormData({...formData, nome: e.target.value})} 
                            placeholder="Es. Mario" 
                            required 
                        />
                    </div>
                    <SelectField 
                        id="student-classe-select" // FIX: Add ID
                        name="classe" // FIX: Add name
                        label="Classe" 
                        value={formData.classe} 
                        onChange={e => setFormData({...formData, classe: e.target.value})} 
                        required
                    >
                        {userClasses.map(c => <option key={c} value={c}>{c}</option>)}
                    </SelectField>
                </div>
                <div className="dialog-footer">
                    <button type="button" onClick={onClose} className="button button-text rounded-lg hover:shadow-md transition-all">Annulla</button>
                    <button type="submit" className="button button-filled rounded-lg hover:shadow-md transition-all">Salva Studente</button>
                </div>
            </form>
        </div>
    );
};

export default AddStudentModal;
