
import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from '@google/genai';

interface VideoAnalysisModalProps {
    onClose: () => void;
}

const loadingMessages = [
    "Inizializzazione del modello Veo...",
    "Analisi del prompt in corso...",
    "I fotogrammi stanno prendendo vita...",
    "Renderizzazione del video ad alta definizione...",
    "Quasi pronto, applicando gli ultimi ritocchi...",
];

const VideoAnalysisModal: React.FC<VideoAnalysisModalProps> = ({ onClose }) => {
    const [hasApiKey, setHasApiKey] = useState<boolean | null>(null);
    const [prompt, setPrompt] = useState<string>('');
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [loadingMessage, setLoadingMessage] = useState<string>(loadingMessages[0]);
    const [error, setError] = useState<string>('');
    const [generatedVideoUrl, setGeneratedVideoUrl] = useState<string | null>(null);

    useEffect(() => {
        // GUIDELINE: Use window.aistudio.hasSelectedApiKey() to check for selected key
        if (window.aistudio) {
            window.aistudio.hasSelectedApiKey().then(setHasApiKey);
        } else {
            // Check if injected via process.env
            setHasApiKey(!!import.meta.env.VITE_GEMINI_API_KEY);
        }
    }, []);

    useEffect(() => {
        let interval: number;
        if (isLoading) {
            let i = 0;
            interval = window.setInterval(() => {
                i = (i + 1) % loadingMessages.length;
                setLoadingMessage(loadingMessages[i]);
            }, 5000);
        }
        return () => clearInterval(interval);
    }, [isLoading]);

    const handleSelectKey = async () => {
        if (window.aistudio) {
            await window.aistudio.openSelectKey();
            // GUIDELINE: MUST assume key selection was successful after triggering openSelectKey()
            setHasApiKey(true);
        } else {
            alert("Per favore configura l'API Key nel tuo ambiente.");
        }
    };

    const handleSubmit = async () => {
        if (!prompt) {
            setError("Per favore, inserisci un prompt per generare il video.");
            return;
        }
        setError('');
        setIsLoading(true);
        setGeneratedVideoUrl(null);
        setLoadingMessage(loadingMessages[0]);

        try {
            // GUIDELINE: Create new GoogleGenAI instance right before call
            const ai = new GoogleGenAI(import.meta.env.VITE_GEMINI_API_KEY);

            // Veo model parameters
            let operation = await (ai as any).models.generateVideos({
                model: 'veo-3.1-fast-generate-preview',
                prompt: prompt,
                config: {
                    numberOfVideos: 1,
                    resolution: '720p',
                    aspectRatio: '16:9'
                }
            });

            while (!operation.done) {
                await new Promise(resolve => setTimeout(resolve, 10000));
                operation = await (ai as any).operations.getVideosOperation({ operation: operation });
            }

            if (operation.error) {
                // GUIDELINE: Reset key if "Requested entity was not found" error occurs
                if (operation.error.message.includes("Requested entity was not found.")) {
                    setError("API Key non valida o permessi mancanti. Per favore, seleziona nuovamente la chiave.");
                    setHasApiKey(false);
                    return;
                }
                throw new Error(operation.error.message || 'Errore durante la generazione del video.');
            }

            const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;

            if (downloadLink) {
                // GUIDELINE: Append API key when fetching from download link
                const urlWithKey = `${downloadLink}&key=${import.meta.env.VITE_GEMINI_API_KEY}`;
                const response = await fetch(urlWithKey);
                if (!response.ok) {
                    throw new Error(`Errore nel download del video: ${response.statusText}`);
                }
                const videoBlob = await response.blob();
                const videoUrl = URL.createObjectURL(videoBlob);
                setGeneratedVideoUrl(videoUrl);
            } else {
                throw new Error("Nessun link per il download del video trovato nella risposta.");
            }

        } catch (err: unknown) {
            console.error("Error during video generation:", err);
            const errorMessage = (err instanceof Error) ? err.message : String(err);
            setError(`Errore durante la generazione: ${errorMessage}`);
        } finally {
            setIsLoading(false);
        }
    };

    const renderContent = () => {
        if (hasApiKey === null) {
            return <div className="flex items-center justify-center h-full"><div className="animate-spin rounded-full h-16 w-16 border-b-2 border-primary"></div></div>;
        }

        if (!hasApiKey) {
            return (
                <div className="flex flex-col items-center justify-center h-full text-center p-8">
                    <div className="card max-w-lg text-center">
                        <span className="material-symbols-outlined text-5xl text-primary">vpn_key</span>
                        <h3 className="m3-headline-medium mt-4 mb-2">API Key Richiesta</h3>
                        <p className="m3-body-medium text-on-surface-variant max-w-md mb-6">
                            Per utilizzare la generazione video (modello Veo), è necessaria una API Key abilitata al billing.
                            <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" className="link-button ml-1">
                                Scopri di più
                            </a>
                        </p>
                        {window.aistudio && (
                            <button onClick={handleSelectKey} className="button button-filled">Seleziona API Key</button>
                        )}
                    </div>
                </div>
            );
        }

        return (
            <div className="dialog-content-grid-tall">
                <div className="p-4 md:p-6 border-r border-outline-variant flex flex-col gap-4">
                    <div>
                        <h3 className="m3-title-medium mb-2">1. Prompt Descrittivo</h3>
                        <p className="m3-body-medium text-on-surface-variant">Descrivi la scena che vuoi creare. Sii dettagliato per un risultato migliore.</p>
                    </div>
                    <textarea
                        id="prompt-textarea"
                        value={prompt}
                        onChange={(e) => {
                            setPrompt(e.target.value);
                            if (error) setError('');
                        }}
                        placeholder="Es. 'Un gatto astronauta fluttua nello spazio, inseguendo un gomitolo di lana cosmico'..."
                        className="form-textarea w-full flex-grow"
                        rows={10}
                    />
                    <button onClick={handleSubmit} disabled={isLoading || !prompt} className="button button-filled w-full mt-auto">
                        {isLoading ? 'Generazione...' : 'Genera Video'}
                    </button>
                    {error && <p className="text-error text-sm mt-2 text-center">{error}</p>}
                </div>

                <div className="p-4 md:p-6 overflow-y-auto flex flex-col items-center justify-center bg-surface-container-lowest">
                    {isLoading && (
                        <div className="text-center">
                            <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-primary mx-auto"></div>
                            <p className="mt-4 m3-title-medium">{loadingMessage}</p>
                            <p className="m3-body-medium text-on-surface-variant">Questa operazione può richiedere alcuni minuti.</p>
                        </div>
                    )}
                    {generatedVideoUrl && !isLoading && (
                        <div className="w-full">
                            <h3 className="m3-title-medium mb-2">Video Generato</h3>
                            <video src={generatedVideoUrl} controls autoPlay loop className="w-full rounded-lg shadow-lg aspect-video bg-black"></video>
                        </div>
                    )}
                    {!generatedVideoUrl && !isLoading && (
                        <div className="text-center text-on-surface-variant p-4">
                            <span className="material-symbols-outlined text-6xl">movie</span>
                            <p>Il video generato apparirà qui.</p>
                        </div>
                    )}
                </div>
            </div>
        )
    };

    return (
        <div className="dialog-backdrop">
            <div className="dialog-container w-full max-w-4xl h-[90vh]">
                <div className="dialog-header">
                    <h2 className="m3-headline-medium">Generazione Video con AI</h2>
                    <button onClick={onClose} className="icon-button">
                        <span className="material-symbols-outlined">close</span>
                    </button>
                </div>
                {renderContent()}
            </div>
        </div>
    );
};

export default VideoAnalysisModal;
