
import React, { useState } from 'react';
import { AiSettings, CircularAnalysisResult, EventoCalendario } from '../types';
import { analyzeCircularDocument } from '../services/aiService';

interface CircolareAnalysisModalProps {
    url: string; // URL is passed for reference (to open in new tab), not for fetching
    title: string;
    onClose: () => void;
    aiSettings: AiSettings;
    onImportEvents: (events: Partial<EventoCalendario>[]) => void;
    onSaveToKb: (note: { title: string, content: string }) => void;
}

const CircolareAnalysisModal: React.FC<CircolareAnalysisModalProps> = (props) => {
    const { url, title, onClose, aiSettings, onImportEvents, onSaveToKb } = props;

    const [manualText, setManualText] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');
    const [result, setResult] = useState<CircularAnalysisResult | null>(null);

    const handleAnalyze = async () => {
        if (!manualText.trim()) {
            setError("Per favore, incolla il testo della circolare.");
            return;
        }

        setIsLoading(true);
        setError('');
        try {
            // We pass fileContent instead of url to enforce text-only analysis
            const analysisResult = await analyzeCircularDocument(aiSettings, { fileContent: manualText });
            setResult(analysisResult);
        } catch (error: any) {
            setError(error.message || 'Si è verificato un errore sconosciuto durante l\'analisi.');
        } finally {
            setIsLoading(false);
        }
    };

    const handleImport = () => {
        if (!result) return;
        
        const allEvents: Partial<EventoCalendario>[] = result.events.map(e => ({
            ...e,
            tipo: 'impegno'
        }));

        result.deadlines.forEach(d => {
            allEvents.push({
                titolo: d.title,
                data: d.date,
                tipo: 'scadenza',
            });
        });

        if (allEvents.length > 0) {
            onImportEvents(allEvents);
        }

        if (result.notes && result.notes.title && result.notes.content) {
            onSaveToKb(result.notes);
        }
        
        onClose();
    };

    return (
        <div className="dialog-backdrop">
            <div className="dialog-container w-full max-w-2xl">
                <div className="dialog-header">
                     <div>
                        <h2 className="m3-headline-medium">Analisi Circolare</h2>
                        <p className="m3-body-medium text-on-surface-variant truncate max-w-md">{title}</p>
                    </div>
                    <button onClick={onClose} className="icon-button">
                        <span className="material-symbols-outlined">close</span>
                    </button>
                </div>
                
                <div className="dialog-content space-y-4">
                    {!result ? (
                        /* INPUT STATE */
                        <>
                            <div className="bg-surface-container-high p-4 rounded-xl border border-outline-variant">
                                <h3 className="m3-title-small font-bold mb-2">Procedura Manuale (Privacy-Safe)</h3>
                                <ol className="list-decimal pl-5 space-y-2 text-sm text-on-surface-variant">
                                    <li>
                                        <a href={url} target="_blank" rel="noopener noreferrer" className="text-primary hover:underline font-bold">
                                            Apri la circolare originale <span className="material-symbols-outlined text-xs align-middle">open_in_new</span>
                                        </a>
                                    </li>
                                    <li>Seleziona e copia il testo del documento.</li>
                                    <li>Incolla il testo nel box qui sotto.</li>
                                </ol>
                            </div>

                            <textarea
                                value={manualText}
                                onChange={(e) => setManualText(e.target.value)}
                                className="form-textarea w-full"
                                rows={8}
                                placeholder="Incolla qui il testo della circolare..."
                                disabled={isLoading}
                            />
                            
                            {error && <p className="text-error text-sm text-center">{error}</p>}
                        </>
                    ) : (
                        /* RESULT STATE */
                        <div className="space-y-4 animate-in fade-in">
                            <div className="p-3 bg-secondary-container text-on-secondary-container rounded-lg">
                                <h3 className="font-bold text-sm mb-1">Riepilogo AI</h3>
                                <p className="text-sm">{result.summary}</p>
                            </div>

                            {result.events.length > 0 || result.deadlines.length > 0 ? (
                                <div className="border border-outline-variant rounded-lg overflow-hidden">
                                    <div className="bg-surface-container px-3 py-2 border-b border-outline-variant">
                                        <h4 className="text-xs font-bold uppercase tracking-wider text-on-surface-variant">Eventi Trovati</h4>
                                    </div>
                                    <ul className="divide-y divide-outline-variant">
                                        {result.events.map((e, i) => (
                                            <li key={i} className="p-3 text-sm flex justify-between">
                                                <span>{e.titolo}</span>
                                                <span className="font-mono text-xs bg-surface-container-high px-2 py-0.5 rounded">{e.data}</span>
                                            </li>
                                        ))}
                                        {result.deadlines.map((d, i) => (
                                            <li key={`d-${i}`} className="p-3 text-sm flex justify-between bg-error-container/10">
                                                <span className="flex items-center gap-2"><span className="material-symbols-outlined text-error text-xs">flag</span> {d.title}</span>
                                                <span className="font-mono text-xs bg-error-container text-on-error-container px-2 py-0.5 rounded">{d.date}</span>
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                            ) : (
                                <p className="text-center text-sm text-on-surface-variant italic">Nessun evento o scadenza rilevato nel testo.</p>
                            )}
                        </div>
                    )}
                </div>

                <div className="dialog-footer">
                    {!result ? (
                        <>
                            <button onClick={onClose} className="button button-text" disabled={isLoading}>Annulla</button>
                            <button onClick={handleAnalyze} disabled={isLoading || !manualText.trim()} className="button button-filled">
                                {isLoading ? (
                                    <>
                                        <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-on-primary mr-2"></div>
                                        Analisi...
                                    </>
                                ) : (
                                    <>
                                        <span className="material-symbols-outlined mr-2">auto_awesome</span>
                                        Analizza Testo
                                    </>
                                )}
                            </button>
                        </>
                    ) : (
                        <>
                            <button onClick={() => setResult(null)} className="button button-text">Indietro</button>
                            <button onClick={handleImport} className="button button-filled">
                                <span className="material-symbols-outlined mr-2">save</span>
                                Salva Eventi e Note
                            </button>
                        </>
                    )}
                </div>
            </div>
        </div>
    );
};

export default CircolareAnalysisModal;
