
import React, { useState } from 'react';
import { Valutazione } from '../types';
import { EVALUATION_TYPES } from '../constants';
import { M3ChoiceCard } from './M3Components';

interface AddProvaModalProps {
    disciplines: string[];
    onClose: () => void;
    onSave: (prova: Omit<Valutazione, 'id' | 'studenteId' | 'voto'>) => void;
}

const getTestTypeIcon = (tipo: string) => {
    switch(tipo) {
        case 'Scritto': return 'edit_note';
        case 'Orale': return 'record_voice_over';
        case 'Pratico': return 'build';
        case 'Test': return 'quiz';
        case 'Verifica': return 'assignment_late';
        default: return 'assignment';
    }
};

const AddProvaModal: React.FC<AddProvaModalProps> = ({ disciplines, onClose, onSave }) => {
    const [materia, setMateria] = useState<string>((disciplines && disciplines[0]) || '');
    const [tipo, setTipo] = useState<Valutazione['tipo']>('Scritto');
    const [data, setData] = useState<string>(new Date().toISOString().split('T')[0]);
    const [argomento, setArgomento] = useState<string>('');

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!materia || !tipo || !data || !argomento) {
            alert("Compila tutti i campi per definire la prova.");
            return;
        }
        onSave({
            materia,
            data,
            tipo,
            argomento,
            note: '',
        });
        onClose();
    };

    return (
        <div className="dialog-backdrop">
            <form onSubmit={handleSubmit} className="dialog-container w-full max-w-lg">
                <div className="dialog-header">
                    <h2 className="m3-headline-medium font-black">Aggiungi Prova di Valutazione</h2>
                    <button type="button" onClick={onClose} className="icon-button rounded-lg hover:shadow-md transition-all">
                        <span className="material-symbols-outlined">close</span>
                    </button>
                </div>
                <div className="dialog-content space-y-4">
                    <p className="m3-body-medium text-on-surface-variant">
                        Stai creando una nuova colonna nella griglia di valutazione per la classe selezionata.
                    </p>
                    <div>
                        <label htmlFor="prova-argomento" className="form-label">Titolo / Argomento della Prova</label>
                        <input id="prova-argomento" name="prova-argomento" type="text" value={argomento} onChange={e => setArgomento(e.target.value)} className="form-input w-full" placeholder="Es. 'Verifica sul Barocco'" required />
                    </div>
                    <div className="form-grid-2">
                        <div>
                            <label htmlFor="prova-data" className="form-label">Data</label>
                            <input id="prova-data" name="prova-data" type="date" value={data} onChange={e => setData(e.target.value)} className="form-input w-full" required />
                        </div>
                        <div>
                            <label htmlFor="prova-materia" className="form-label">Materia</label>
                            <select id="prova-materia" name="prova-materia" value={materia} onChange={e => setMateria(e.target.value)} className="form-select w-full" required>
                                {(disciplines || []).map(d => <option key={d} value={d}>{d}</option>)}
                            </select>
                        </div>
                    </div>
                    <div>
                        <label className="form-label">Tipo Prova</label>
                        <div className="flex gap-2">
                            {EVALUATION_TYPES.map(t => (
                                <M3ChoiceCard
                                    key={t}
                                    icon={getTestTypeIcon(t)}
                                    label={t}
                                    onClick={() => setTipo(t)}
                                    selected={tipo === t}
                                />
                            ))}
                        </div>
                    </div>
                </div>
                <div className="dialog-footer">
                    <button type="button" onClick={onClose} className="button button-text rounded-lg hover:shadow-md transition-all">Annulla</button>
                    <button type="submit" className="button button-filled rounded-lg hover:shadow-md transition-all">Crea Prova</button>
                </div>
            </form>
        </div>
    );
};

export default AddProvaModal;
