
import React, { useState } from 'react';
import { QuestionType } from '../types';
import { TabGroup, TextField } from './M3Components';

interface TestGeneratorModalProps {
    onClose: () => void;
    onGenerate: (config: {
        topic: string;
        difficulty: 'easy' | 'medium' | 'hard';
        questionCount: number;
        questionTypes: QuestionType[];
    }) => void;
}

const TestGeneratorModal: React.FC<TestGeneratorModalProps> = ({ onClose, onGenerate }) => {
    const [topic, setTopic] = useState('');
    const [difficulty, setDifficulty] = useState<'easy' | 'medium' | 'hard'>('medium');
    const [questionCount, setQuestionCount] = useState(10);
    const [questionTypes, setQuestionTypes] = useState<QuestionType[]>(['multiple_choice']);

    const toggleQuestionType = (type: QuestionType) => {
        setQuestionTypes(prev => prev.includes(type) ? prev.filter(t => t !== type) : [...prev, type]);
    };

    const handleSubmit = () => {
        if (questionTypes.length === 0) { alert("Seleziona un tipo di domanda."); return; }
        onGenerate({ topic: topic || 'Argomenti KB', difficulty, questionCount, questionTypes });
    };

    return (
        <div className="dialog-backdrop">
            <div className="dialog-container w-full max-w-lg shadow-3xl">
                <div className="dialog-header border-b border-outline-variant">
                    <h2 className="m3-headline-medium font-black">Generatore Verifiche</h2>
                    <button onClick={onClose} className="icon-button"><span className="material-symbols-outlined">close</span></button>
                </div>
                <div className="dialog-content p-6 space-y-8">
                    <TextField 
                        id="test-topic-input"
                        label="Argomento Specifico" 
                        value={topic} 
                        onChange={e => setTopic(e.target.value)} 
                        placeholder="Es. Rivoluzione Francese" 
                    />

                    <div>
                        <label className="text-[11px] text-primary font-black uppercase tracking-[0.2em] px-2 mb-3 block">Difficoltà</label>
                        <TabGroup
                            tabs={[{ id: 'easy', label: 'Base' }, { id: 'medium', label: 'Intermedio' }, { id: 'hard', label: 'Avanzato' }]}
                            activeTab={difficulty}
                            onTabChange={(id) => setDifficulty(id as any)}
                            variant="primary"
                            className="w-full"
                        />
                    </div>

                    <div className="p-5 bg-surface-container rounded-3xl border border-outline-variant">
                         <div className="flex justify-between items-center mb-4 px-1">
                            <label htmlFor="test-qcount-slider" className="m3-label-large font-black uppercase text-primary tracking-widest">Numero Quesiti</label>
                            <span className="text-xl font-black text-primary">{questionCount}</span>
                        </div>
                         <input id="test-qcount-slider" name="test-qcount-slider" type="range" min="5" max="20" value={questionCount} onChange={e => setQuestionCount(parseInt(e.target.value))} className="w-full accent-primary" />
                    </div>

                    <div className="space-y-3">
                        <label className="text-[11px] text-primary font-black uppercase tracking-[0.2em] px-2 block">Tipi di Domande</label>
                        <div className="m3-chip-grid">
                             <div className="chip-checkbox">
                                <input type="checkbox" id="q-mc" checked={questionTypes.includes('multiple_choice')} onChange={() => toggleQuestionType('multiple_choice')} />
                                <label htmlFor="q-mc" className={`chip ${questionTypes.includes('multiple_choice') ? 'chip-selected' : ''}`}>Scelta Multipla</label>
                            </div>
                            <div className="chip-checkbox">
                                <input type="checkbox" id="q-tf" checked={questionTypes.includes('true_false')} onChange={() => toggleQuestionType('true_false')} />
                                <label htmlFor="q-tf" className={`chip ${questionTypes.includes('true_false') ? 'chip-selected' : ''}`}>Vero/Falso</label>
                            </div>
                        </div>
                    </div>
                </div>
                <div className="dialog-footer border-t border-outline-variant">
                    <button onClick={onClose} className="button button-text">Annulla</button>
                    <button onClick={handleSubmit} className="button button-filled shadow-xl font-black"><span className="material-symbols-outlined mr-2">auto_awesome</span> Genera</button>
                </div>
            </div>
        </div>
    );
};

export default TestGeneratorModal;
