import React from 'react';
import { View, Lezione, Slot, AppState, UserProfile, AiSuggestion, RegisterEntry, TimetableSettings } from '../types';
import { ActionTile, SectionHeader, InfoCard } from './M3Components';
import ContextualStrip from './ContextualStrip';

interface HomeProps {
    slots: Record<string, Slot>;
    lessons: Record<string, Lezione>;
    onNavigate: (view: View, context?: any) => void;
    appState: AppState; // Full app state
    onSuggestionAction: (action: AiSuggestion['action']) => void;
    onStartClassroom: (classe: string, materia: string, slotKey: string, lesson: Lezione) => void;
    finalizedRegister: RegisterEntry[];
    draftRegister: Record<string, RegisterEntry>;
    showGuidanceTips: boolean;
    suggestions: AiSuggestion[];
    onAiProcessing: (processing: boolean) => void;
    user: UserProfile | null;
    onUpdateMemos: (memos: any) => void;
    onConnectDrive: () => void;
    aiSettings: AppState['aiSettings'];
    settings: TimetableSettings;
    dismissSuggestion: (id: string) => void; // FIX: Added missing prop
    handleOpenOperations: () => void; // FIX: Added missing prop
}

const Home: React.FC<HomeProps> = ({ slots, lessons, onNavigate, appState, onSuggestionAction, onStartClassroom, finalizedRegister, draftRegister, showGuidanceTips, suggestions, onAiProcessing, user, onUpdateMemos, onConnectDrive, aiSettings, settings, dismissSuggestion, handleOpenOperations }) => {
    // Determine current lesson for the hero card
    const now = new Date();
    const currentDay = now.toLocaleDateString('it-IT', { weekday: 'long' });
    const currentHour = now.getHours();
    const currentMinute = now.getMinutes();

    const todaysSlots = Object.values(slots).filter((s: Slot) => s.giorno === currentDay);
    const upcomingLessons = todaysSlots
        .map((slot: Slot) => ({
            slot,
            lesson: slot.lezioneId ? lessons[slot.lezioneId] : null
        }))
        .filter(item => item.lesson && !item.lesson.svolta)
        .sort((a, b) => {
            const [h1, m1] = a.slot.ora.split(':').map(Number);
            const [h2, m2] = b.slot.ora.split(':').map(Number);
            if (h1 !== h2) return h1 - h2;
            return m1 - m2;
        });

    // Find a lesson that is current or immediately next
    const activeLessonForHero = upcomingLessons.find(item => {
        const [h, m] = (item.slot as Slot).ora.split(':').map(Number);
        const lessonStartMinutes = h * 60 + m;
        const lessonEndMinutes = lessonStartMinutes + 60; // Assume 1 hour
        const nowInMinutes = currentHour * 60 + currentMinute;
        return nowInMinutes >= lessonStartMinutes && nowInMinutes < lessonEndMinutes;
    }) || upcomingLessons[0]; // If no current, take the very next one


    const handleHeroClick = () => {
        if (activeLessonForHero?.lesson) {
            onStartClassroom(
                (activeLessonForHero.lesson as Lezione).classe,
                (activeLessonForHero.lesson as Lezione).materia,
                `${(activeLessonForHero.slot as Slot).giorno}-${(activeLessonForHero.slot as Slot).ora}`,
                activeLessonForHero.lesson as Lezione
            );
        } else {
            handleOpenOperations(); // Fallback to operations center if no specific lesson
        }
    };

    const activeSuggestion = appState.activeSuggestion;
    const dismissedSuggestions = appState.dismissedSuggestions;


    return (
        <div className="page-layout p-4 md:p-8 space-y-12">

            {activeSuggestion && !dismissedSuggestions.has(activeSuggestion.id) && (
                <ContextualStrip
                    message={activeSuggestion.message}
                    actionLabel={activeSuggestion.actionLabel}
                    onAction={() => onSuggestionAction(activeSuggestion.action)}
                    onDismiss={() => dismissSuggestion(activeSuggestion.id)}
                    visible={true}
                />
            )}

            {/* --- COMMAND CENTER HERO --- */}
            <section className="animate-in fade-in slide-in-from-bottom-8 duration-700">
                {activeLessonForHero?.lesson ? (
                    <div className="hero-card">
                        <div className="flex flex-col lg:flex-row justify-between items-center gap-10">
                            <div className="space-y-4 text-center lg:text-left flex-grow">
                                <div className="inline-flex items-center gap-2 bg-primary text-on-primary px-5 py-2 rounded-full font-black tracking-widest uppercase text-xs shadow-lg">
                                    <span className="relative flex h-2 w-2">
                                        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-white opacity-75"></span>
                                        <span className="relative inline-flex rounded-full h-2 w-2 bg-white"></span>
                                    </span>
                                    In Sessione
                                </div>
                                <h1 className="m3-display-medium font-black text-on-primary-container leading-tight">{activeLessonForHero.lesson.materia} • Classe {activeLessonForHero.lesson.classe}</h1>
                                <p className="m3-headline-small text-on-primary-container opacity-90 font-bold italic">"{activeLessonForHero.lesson.contenuto}"</p>
                            </div>
                            <div className="w-32 h-32 rounded-[40px] bg-white/20 backdrop-blur-2xl border border-white/30 flex items-center justify-center text-on-primary-container shadow-2xl transition-transform hover:rotate-12">
                                <span className="material-symbols-outlined text-7xl font-light">school</span>
                            </div>
                        </div>
                        <button
                            onClick={handleHeroClick}
                            className="button button-filled bg-primary text-on-primary mt-12 w-full !h-16 !rounded-3xl font-black text-xl shadow-2xl hover:scale-[1.03] active:scale-95 transition-all flex items-center justify-center gap-4"
                        >
                            Gestisci Classe <span className="material-symbols-outlined text-3xl">play_circle</span>
                        </button>
                    </div>
                ) : (
                    <div className="hero-card bg-surface-variant text-on-surface-variant">
                        <div className="flex flex-col lg:flex-row justify-between items-center gap-10">
                            <div className="space-y-4 text-center lg:text-left flex-grow">
                                <h1 className="m3-display-medium font-black leading-tight">Benvenuto {user?.displayName || 'Docente'}</h1>
                                <p className="m3-headline-small opacity-90 font-bold italic">Nessuna lezione in corso. Pianifica il tuo anno o avvia una lezione rapida!</p>
                            </div>
                            <div className="w-32 h-32 rounded-[40px] bg-white/20 backdrop-blur-2xl border border-white/30 flex items-center justify-center text-on-surface-variant shadow-2xl">
                                <span className="material-symbols-outlined text-7xl font-light">waving_hand</span>
                            </div>
                        </div>
                        <button
                            onClick={() => onNavigate('progettazione-hub', { action: 'annual-planning' })}
                            className="button button-filled bg-secondary text-on-secondary mt-12 w-full !h-16 !rounded-3xl font-black text-xl shadow-2xl hover:scale-[1.03] active:scale-95 transition-all flex items-center justify-center gap-4"
                        >
                            <span className="material-symbols-outlined text-3xl">calendar_month</span> Inizia a Pianificare
                        </button>
                    </div>
                )}
            </section>

            {/* --- CORE OPERATIONS BENTO GRID --- */}
            <section className="animate-in fade-in slide-in-from-bottom-10 delay-150 duration-700">
                <SectionHeader title="Centro Operativo Intelligente" icon="electric_bolt" />
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                    <ActionTile
                        title="Registro Classe"
                        subtitle="Presenze e Valutazioni"
                        icon="auto_stories"
                        variant="primary"
                        onClick={() => onNavigate('aula')}
                        className="lg:col-span-2 !py-10"
                    />
                    <ActionTile
                        title="Progettazione"
                        subtitle="UDA e Lezioni"
                        icon="account_tree"
                        variant="secondary"
                        onClick={() => onNavigate('progettazione-hub')}
                        className="!py-10"
                    />
                    <ActionTile
                        title="AI Lab"
                        subtitle="Studio e Materiali"
                        icon="auto_fix_high"
                        variant="tertiary"
                        onClick={() => onNavigate('studio')}
                        className="!py-10"
                    />
                </div>
            </section>

            {/* --- SMART INSIGHTS --- */}
            <section className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in fade-in slide-in-from-bottom-12 delay-300 duration-700">
                <InfoCard
                    title="Analisi Didattica Inclusiva"
                    description="Strategie personalizzate AI per supportare ogni studente nel proprio percorso di apprendimento."
                    icon="diversity_3"
                    variant="tertiary"
                    className="!p-8"
                    action={<button onClick={() => onNavigate('didattica-inclusiva')} className="button button-filled bg-tertiary !px-8 rounded-full">Gestisci PDP</button>}
                />
                <InfoCard
                    title="Statistiche Rendimento"
                    description="Monitora l'efficacia del tuo metodo con grafici radar e analisi del trend per ogni materia."
                    icon="query_stats"
                    variant="secondary"
                    className="!p-8"
                    action={<button onClick={() => onNavigate('analytics')} className="button button-filled bg-secondary !px-8 rounded-full">Apri Analytics</button>}
                />
            </section>
        </div>
    );
};
export default Home;
