import React, { useState, useCallback, useMemo } from 'react';
import { useDropzone } from 'react-dropzone';
import { Studente, KnowledgeBaseEntry } from '../types';
import { parseCSVWithHeaders } from '../utils/csvUtils';
import { getGoogleAIClient } from '../services/aiClient';
import { TabGroup, TextField, SelectField, TextArea, InfoCard } from './M3Components'; // FIX: Import InfoCard

interface ImportStudentsModalProps {
    onClose: () => void;
    onImport: (newStudents: Studente[]) => void;
    userClasses: string[];
    knowledgeBase: KnowledgeBaseEntry[];
}

const ImportStudentsModal: React.FC<ImportStudentsModalProps> = ({ onClose, onImport, userClasses, knowledgeBase }) => {
    const [step, setStep] = useState<'upload' | 'mapping' | 'confirm'>('upload');
    const [importSource, setImportSource] = useState<'file' | 'kb'>('file');
    const [targetClass, setTargetClass] = useState<string>(userClasses[0] || 'AUTO');
    const [csvData, setCsvData] = useState<Record<string, string>[]>([]);
    const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
    const [columnMap, setColumnMap] = useState({ cognome: '', nome: '', classe: '' });
    const [error, setError] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [fileName, setFileName] = useState('');
    const [infoMessage, setInfoMessage] = useState('');

    const processFileContent = useCallback((content: string, name: string) => {
        setFileName(name);
        setError('');
        setInfoMessage('');

        try {
            const { headers, data } = parseCSVWithHeaders(content);

            if (headers.length === 0 || data.length === 0) {
                throw new Error("Il file CSV è vuoto o non ha una riga di intestazione valida.");
            }
            
            setCsvHeaders(headers);
            setCsvData(data);
            
            let cognomeCol = '';
            let nomeCol = '';
            let classeCol = '';

            for (const header of headers) {
                const lowerHeader = header.toLowerCase();
                if (!cognomeCol && (lowerHeader.includes('cognome') || lowerHeader.includes('last name') || lowerHeader.includes('surname'))) {
                    cognomeCol = header;
                }
                if (!nomeCol && (lowerHeader.includes('nome') || lowerHeader.includes('first name') || lowerHeader.includes('name'))) {
                    nomeCol = header;
                }
                if (!classeCol && (lowerHeader.includes('classe') || lowerHeader.includes('class'))) {
                    classeCol = header;
                }
            }
            setColumnMap({ cognome: cognomeCol, nome: nomeCol, classe: classeCol });
            setStep('mapping');

        } catch (err: any) {
            console.error(err);
            setError(err.message || "Errore durante l'analisi del file.");
            setStep('upload');
        }
    }, []);


    const onDrop = useCallback(async (acceptedFiles: File[]) => {
        if (acceptedFiles.length === 0) return;
        
        setIsLoading(true);
        setError('');
        setInfoMessage('');
        const file = acceptedFiles[0];

        try {
            if (file.type === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' || file.name.endsWith('.xlsx')) {
                const ai = getGoogleAIClient();
                const prompt = `
Sei un assistente AI amichevole e molto chiaro. Un utente ha caricato un file .xlsx, ma l'applicazione accetta solo file .csv. 
Genera una risposta in formato Markdown con istruzioni semplici e separate per Microsoft Excel e Google Sheets su come salvare il file in formato CSV.
Usa titoli e grassetto per chiarezza. Sii conciso e vai dritto al punto.
`;
                const response = await ai.models.generateContent({
                    model: 'gemini-2.5-flash',
                    contents: prompt,
                });
                setInfoMessage(response.text || ''); // FIX: Ensure text is not undefined
                setIsLoading(false);
                return;
            }

            if (file.type !== 'text/csv' && !file.name.endsWith('.csv')) {
                 throw new Error("Tipo di file non supportato. Carica un file .csv o .xlsx.");
            }

            const fileContent = await file.text();
            processFileContent(fileContent, file.name);

        } catch (err: any) {
            console.error(err);
            setError(err.message || "Errore durante l'analisi del file.");
            setStep('upload');
        } finally {
            setIsLoading(false);
        }
    }, [processFileContent]);

    const { getRootProps, getInputProps, isDragActive } = useDropzone({
        onDrop,
        accept: { 
            'text/csv': ['.csv'],
            'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx'] 
        },
        multiple: false,
        disabled: isLoading
    });

    const handleKbFileSelect = (entry: KnowledgeBaseEntry) => {
        if (!entry.content) {
            setError("Il file selezionato non ha contenuto testuale leggibile.");
            return;
        }
        processFileContent(entry.content, entry.fileName);
    };

    const studentsToImport = useMemo(() => {
        if (!columnMap.cognome || !columnMap.nome || csvData.length === 0) {
            return [];
        }
        
        if (targetClass === 'AUTO' && !columnMap.classe) {
            return [];
        }

        return csvData
            .map(row => {
                const extractedClass = targetClass === 'AUTO' ? (row[columnMap.classe] || '').trim() : targetClass;
                const normalizedClass = extractedClass.replace(/\s+/g, '').toUpperCase();

                return {
                    cognome: row[columnMap.cognome] || '',
                    nome: row[columnMap.nome] || '',
                    classe: normalizedClass,
                }
            })
            .filter(s => s.cognome.trim() && s.nome.trim() && s.classe);
    }, [csvData, columnMap, targetClass]);
    
    const handleImport = () => {
        const finalStudents: Studente[] = studentsToImport.map(s => ({
            ...s,
            id: `stud-${Date.now()}-${Math.random()}`
        }));
        onImport(finalStudents);
        onClose();
    };

    const renderUploadStep = () => (
        <>
            <div className="space-y-6">
                <div>
                    <SelectField 
                        id="import-target-class" // FIX: Add ID
                        label="Destinazione" 
                        value={targetClass} 
                        onChange={e => setTargetClass(e.target.value)} 
                        required
                    >
                        <option value="AUTO">✨ Rileva automaticamente dal file (Multi-classe)</option>
                        <option disabled>──────────</option>
                        {userClasses.map(c => <option key={c} value={c}>{c}</option>)}
                    </SelectField>
                    {targetClass === 'AUTO' && <p className="text-[10px] text-on-surface-variant mt-1 px-2">Il file CSV deve contenere una colonna con il nome della classe (es. "1A", "2B").</p>}
                </div>
                
                <TabGroup
                    tabs={[{ id: 'file', label: 'Carica File' }, { id: 'kb', label: 'Da Knowledge Base' }]}
                    activeTab={importSource}
                    onTabChange={(id) => setImportSource(id as any)}
                    variant="secondary"
                    className="w-full"
                />

                {importSource === 'file' ? (
                    <div>
                        <InfoCard
                            title="Formato Richiesto"
                            description={`Il file deve essere un .CSV con una riga di intestazione (Cognome, Nome${targetClass === 'AUTO' ? ', Classe' : ''}).`}
                            action={
                                <a 
                                    href={`data:text/csv;charset=utf-8,Cognome,Nome${targetClass === 'AUTO' ? ',Classe' : ''}%0ARossi,Mario${targetClass === 'AUTO' ? ',1A' : ''}%0ABianchi,Giulia${targetClass === 'AUTO' ? ',2B' : ''}`} 
                                    download="modello_studenti.csv"
                                    className="button button-tonal !h-auto !py-1 !px-3 !text-xs rounded-lg hover:shadow-md transition-all"
                                >
                                    <span className="material-symbols-outlined text-sm mr-1">download</span>
                                    Modello
                                </a>
                            }
                            icon="description"
                            variant="surface"
                            className="mb-4 !p-4 !rounded-2xl"
                        />

                        <div 
                            {...getRootProps()}
                            className={`dropzone-area h-48 !rounded-[32px] border-2 border-dashed ${isLoading ? 'disabled' : ''} ${isDragActive ? 'border-primary bg-primary-container/10' : 'border-outline-variant'} transition-all`}
                        >
                            <input {...getInputProps()} />
                            {isLoading ? (
                                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                            ) : (
                                <>
                                    <span className="material-symbols-outlined text-5xl text-primary mb-4">{isDragActive ? 'download' : 'upload_file'}</span>
                                    <p className="m3-body-large font-black text-on-surface">Trascina il file .csv o .xlsx qui</p>
                                    <p className="text-[10px] opacity-60 mt-2 font-bold uppercase tracking-widest">o clicca per selezionare</p>
                                </>
                            )}
                        </div>
                    </div>
                ) : (
                    <div>
                         <p className="form-label">Seleziona un file CSV dalla KB</p>
                         <div className="selection-container !bg-surface-container-low !rounded-[24px] max-h-[200px] p-2 border border-outline-variant/30">
                            {knowledgeBase.length > 0 ? (
                                knowledgeBase.map(entry => (
                                    <div 
                                        key={entry.id} 
                                        onClick={() => handleKbFileSelect(entry)}
                                        className="list-item-card !p-3 rounded-lg hover:bg-surface-container-high transition-all"
                                    >
                                        <span className="material-symbols-outlined text-primary">description</span>
                                        <span className="truncate flex-grow">{entry.fileName}</span>
                                        <span className="material-symbols-outlined text-on-surface-variant">chevron_right</span>
                                    </div>
                                ))
                            ) : (
                                <p className="p-4 text-center text-on-surface-variant">Nessun file nella Knowledge Base.</p>
                            )}
                         </div>
                    </div>
                )}

                {error && <div className="p-4 bg-error-container text-on-error-container rounded-xl text-sm mt-4">{error}</div>}
                {infoMessage && (
                    <div className="info-box prose !bg-tertiary-container !text-on-tertiary-container mt-4">
                        <h3 className="m3-title-medium !text-on-tertiary-container">Conversione da XLSX a CSV</h3>
                        <p dangerouslySetInnerHTML={{ __html: infoMessage.replace(/\n/g, '<br />') }} />
                    </div>
                )}
            </div>
            <div className="dialog-footer">
                <button onClick={onClose} className="button button-text rounded-lg hover:shadow-md transition-all">Annulla</button>
            </div>
        </>
    );
    
    const renderMappingStep = () => (
        <>
            <div className="space-y-6">
                <InfoCard 
                    title="Mappa le colonne" 
                    description={`File: ${fileName} | Destinazione: ${targetClass === 'AUTO' ? 'Rilevamento Automatico' : targetClass}`}
                    icon="auto_awesome"
                    variant="primary"
                    className="!p-6 !rounded-2xl"
                />
                
                <p className="m3-body-medium text-on-surface-variant">
                    Indica quali colonne del file CSV contengono le informazioni necessarie.
                </p>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <SelectField 
                        id="map-cognome" // FIX: Add ID
                        label="Colonna COGNOME" 
                        value={columnMap.cognome} 
                        onChange={e => setColumnMap(p => ({...p, cognome: e.target.value}))}
                    >
                        <option value="">Seleziona...</option>
                        {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                    </SelectField>
                     <SelectField 
                        id="map-nome" // FIX: Add ID
                        label="Colonna NOME" 
                        value={columnMap.nome} 
                        onChange={e => setColumnMap(p => ({...p, nome: e.target.value}))}
                    >
                        <option value="">Seleziona...</option>
                        {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                    </SelectField>
                    {targetClass === 'AUTO' && (
                        <div className="col-span-full">
                            <SelectField 
                                id="map-classe" // FIX: Add ID
                                label="Colonna CLASSE" 
                                value={columnMap.classe} 
                                onChange={e => setColumnMap(p => ({...p, classe: e.target.value}))} 
                            >
                                <option value="">Seleziona...</option>
                                {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                            </SelectField>
                        </div>
                    )}
                </div>
                <h4 className="m3-title-small pt-2">Anteprima Dati</h4>
                <div className="table-container max-h-48 overflow-y-auto border border-outline-variant rounded-xl">
                    <table className="table">
                        <thead>
                            <tr className="bg-surface-container-high">{csvHeaders.map(h => <th key={h}>{h}</th>)}</tr>
                        </thead>
                        <tbody>
                            {csvData.slice(0,3).map((row, index) => (
                                <tr key={index}>
                                    {csvHeaders.map(h => <td key={h}>{row[h]}</td>)}
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
             <div className="dialog-footer">
                <button type="button" onClick={() => { setStep('upload'); setInfoMessage(''); setError(''); }} className="button button-text rounded-lg hover:shadow-md transition-all">Indietro</button>
                <button type="button" onClick={() => setStep('confirm')} disabled={!columnMap.cognome || !columnMap.nome || (targetClass === 'AUTO' && !columnMap.classe)} className="button button-filled rounded-lg hover:shadow-md transition-all">Avanti</button>
            </div>
        </>
    );

    const renderConfirmStep = () => (
        <>
            <div className="space-y-6">
                 <InfoCard 
                    title="Conferma Importazione"
                    description={`Stai per importare ${studentsToImport.length} studenti. Gli studenti già presenti saranno ignorati.`}
                    icon="check_circle"
                    variant="secondary"
                    className="!p-6 !rounded-2xl"
                />
                 {targetClass === 'AUTO' && (
                     <div className="p-4 bg-surface-container-low rounded-xl border border-outline-variant text-sm">
                         <p className="font-bold mb-1">Nota Importante:</p>
                         <p>Gli studenti verranno assegnati alle classi indicate nel file. Se una classe nel file non esiste nelle tue Impostazioni, lo studente verrà comunque importato ma la classe sarà creata implicitamente.</p>
                     </div>
                 )}
                 <div className="table-container max-h-64 overflow-y-auto border border-outline-variant rounded-xl">
                     <table className="table">
                        <thead>
                            <tr className="bg-surface-container-high">
                                <th>Cognome</th>
                                <th>Nome</th>
                                <th>Classe</th>
                            </tr>
                        </thead>
                        <tbody>
                            {studentsToImport.map((student, index) => (
                                <tr key={index}>
                                    <td>{student.cognome}</td>
                                    <td>{student.nome}</td>
                                    <td>{student.classe}</td>
                                </tr>
                            ))}
                        </tbody>
                     </table>
                 </div>
            </div>
             <div className="dialog-footer">
                <button type="button" onClick={() => setStep('mapping')} className="button button-text rounded-lg hover:shadow-md transition-all">Indietro</button>
                <button type="button" onClick={handleImport} className="button button-filled rounded-lg hover:shadow-md transition-all">Importa Studenti</button>
            </div>
        </>
    );

    return (
        <div className="dialog-backdrop">
            <div className="dialog-container w-full max-w-2xl h-[90vh] flex flex-col">
                <div className="dialog-header border-b border-outline-variant p-6">
                    <h2 className="m3-headline-medium font-black">Importa Studenti {step !== 'upload' && `(Passo ${step === 'mapping' ? 2 : 3} di 3)`}</h2>
                    <button type="button" onClick={onClose} className="icon-button rounded-lg hover:shadow-md transition-all">
                        <span className="material-symbols-outlined">close</span>
                    </button>
                </div>
                <div className="dialog-content flex-grow overflow-y-auto p-0">
                    {step === 'upload' && renderUploadStep()}
                    {step === 'mapping' && renderMappingStep()}
                    {step === 'confirm' && renderConfirmStep()}
                </div>
            </div>
        </div>
    );
};

export default ImportStudentsModal;
