import React, { InputHTMLAttributes, SelectHTMLAttributes, TextareaHTMLAttributes } from 'react';

// --- INPUTS M3 HARDENED ---

export const TextField: React.FC<InputHTMLAttributes<HTMLInputElement> & { label: string; error?: boolean; leadingIcon?: string; containerClassName?: string }> = ({ label, error, leadingIcon, containerClassName = '', ...props }) => (
    <div className={`flex flex-col gap-2.5 ${containerClassName}`}>
        <label htmlFor={props.id} className="text-[11px] text-primary font-black uppercase tracking-[0.25em] px-4 text-left">{label}</label>
        <div className={`flex items-center gap-4 p-5 rounded-[24px] bg-surface-container-highest border-b-4 ${error ? 'border-error' : 'border-outline-variant'} focus-within:border-primary focus-within:bg-surface transition-all shadow-inner`}>
            {leadingIcon && <span className="material-symbols-outlined text-on-surface-variant font-black">{leadingIcon}</span>}
            <input {...props} className="bg-transparent border-none w-full outline-none m3-body-large text-on-surface font-black placeholder:opacity-20 text-center md:text-left" />
        </div>
    </div>
);

export const SelectField: React.FC<SelectHTMLAttributes<HTMLSelectElement> & { label: string; containerClassName?: string }> = ({ label, containerClassName = '', children, ...props }) => (
    <div className={`flex flex-col gap-2.5 ${containerClassName}`}>
        <label htmlFor={props.id} className="text-[11px] text-primary font-black uppercase tracking-[0.25em] px-4 text-left">{label}</label>
        <div className="relative">
            <select {...props} className="w-full p-5 rounded-[24px] bg-surface-container-highest border-b-4 border-outline-variant focus:border-primary focus:bg-surface outline-none appearance-none m3-body-large font-black cursor-pointer shadow-inner">
                {children}
            </select>
            <span className="material-symbols-outlined absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none opacity-40 font-black">expand_more</span>
        </div>
    </div>
);

export const TextArea: React.FC<TextareaHTMLAttributes<HTMLTextAreaElement> & { label: string; containerClassName?: string }> = ({ label, containerClassName = '', ...props }) => (
    <div className={`flex flex-col gap-2.5 ${containerClassName}`}>
        <label htmlFor={props.id} className="text-[11px] text-primary font-black uppercase tracking-[0.25em] px-4 text-left">{label}</label>
        <div className={`flex items-center gap-4 p-5 rounded-[24px] bg-surface-container-highest border-b-4 border-outline-variant focus-within:border-primary focus-within:bg-surface transition-all shadow-inner`}>
            <textarea {...props} className="bg-transparent border-none w-full outline-none m3-body-large text-on-surface font-black placeholder:opacity-20 resize-none" rows={props.rows || 3} />
        </div>
    </div>
);

// --- AI MEMORY CHIP ---
export const AiMemoryChip: React.FC<{ label: string }> = ({ label }) => (
    <div className="flex items-center gap-1.5 mt-2 opacity-60 hover:opacity-100 transition-opacity select-none cursor-help" title="Contesto utilizzato dall'AI">
        <span className="material-symbols-outlined text-[12px] text-tertiary font-bold">psychology</span>
        <span className="text-[10px] font-black text-on-surface-variant uppercase tracking-widest">{label}</span>
    </div>
);

// --- ACTION TILE (Bento Style) ---
export const ActionTile: React.FC<{ title: string; subtitle?: string; icon: string; onClick: () => void; variant?: string; className?: string; tooltip?: string }> = ({ title, subtitle, icon, onClick, variant = 'surface', className = '', tooltip }) => (
    <button onClick={onClick} className={`op-tile op-tile-variant-${variant} ${className}`} title={tooltip}>
        <div className="op-tile-icon-container shadow-sm"><span className="material-symbols-outlined">{icon}</span></div>
        <div className="op-tile-content">
            <div className="op-tile-title font-black text-left">{title}</div>
            {subtitle && <div className="op-tile-subtitle text-[11px] font-bold text-left opacity-70 uppercase tracking-wider">{subtitle}</div>}
        </div>
        <span className="material-symbols-outlined op-tile-chevron opacity-30">chevron_right</span>
    </button>
);

// --- INFO CARD ---
export const InfoCard: React.FC<{ title: string; description: string; icon?: string; variant?: string; className?: string; action?: React.ReactNode; onClose?: () => void }> = ({ title, description, icon, variant = 'surface', className = '', action, onClose }) => (
    <div className={`p-8 rounded-[40px] shadow-xl border border-outline-variant/10 overflow-hidden relative group ${className} ${variant === 'primary' ? 'bg-primary-container text-on-primary-container' : variant === 'tertiary' ? 'bg-tertiary-container text-on-tertiary-container' : variant === 'error' ? 'bg-error-container text-on-error-container' : 'bg-surface-container text-on-surface'}`}>
        <div className="flex gap-6 items-start relative z-10">
            {icon && <div className="p-4 rounded-3xl bg-white/20 backdrop-blur-xl flex items-center justify-center shadow-inner"><span className="material-symbols-outlined text-3xl">{icon}</span></div>}
            <div className="flex-grow">
                <h3 className="m3-headline-small font-black mb-2">{title}</h3>
                <p className="m3-body-large opacity-80 leading-relaxed font-medium">{description}</p>
                {action && <div className="mt-6">{action}</div>}
            </div>
            {onClose && (
                 <button onClick={onClose} className="icon-button !w-10 !h-10 opacity-40 hover:opacity-100">
                    <span className="material-symbols-outlined">close</span>
                </button>
            )}
        </div>
    </div>
);

// --- SECTION HEADER ---
export const SectionHeader: React.FC<{ title: string; icon?: string; colorClass?: string }> = ({ title, icon, colorClass = 'text-on-surface' }) => (
    <div className={`flex items-center gap-4 mb-8 mt-12 px-2 ${colorClass}`}>
        {icon && <span className="material-symbols-outlined text-2xl opacity-60 font-bold">{icon}</span>}
        <h3 className="text-[11px] font-black uppercase tracking-[0.4em] opacity-50">{title}</h3>
    </div>
);

// --- TAB GROUP ---
export const TabGroup: React.FC<{ tabs: {id: string, label: string, icon?: string, badge?: number | string}[]; activeTab: string; onTabChange: (id: string) => void; variant?: string; className?: string; isIconOnly?: boolean }> = ({ tabs, activeTab, onTabChange, variant = 'primary', className = '', isIconOnly = false }) => (
    <div className={`flex bg-surface-container-low p-1.5 rounded-full border border-outline-variant w-fit shadow-inner ${className}`}>
        {tabs.map(tab => {
            const isActive = activeTab === tab.id;
            const bgClass = variant === 'primary' ? 'bg-primary text-on-primary' : variant === 'secondary' ? 'bg-secondary text-on-secondary' : 'bg-tertiary text-on-tertiary';
            return (
                <button key={tab.id} onClick={() => onTabChange(tab.id)} className={`px-6 py-2.5 rounded-full text-[11px] font-black tracking-widest transition-all flex items-center gap-2 ${isActive ? `${bgClass} shadow-lg scale-[1.03]` : 'text-on-surface-variant hover:bg-surface-container-high'}`}>
                    {tab.icon && <span className="material-symbols-outlined text-xl">{tab.icon}</span>}
                    {!isIconOnly && <span className="uppercase">{tab.label}</span>}
                    {tab.badge !== undefined && <span className="ml-1 px-1.5 py-0.5 rounded-full bg-black/10 text-[9px]">{tab.badge}</span>}
                </button>
            )
        })}
    </div>
);

// --- PIN PAD ---
export const PinPad: React.FC<{ onInput: (digit: string) => void; onDelete: () => void }> = ({ onInput, onDelete }) => {
    const keys = ['1', '2', '3', '4', '5', '6', '7', '8', '9', '', '0', 'back'];
    return (
        <div className="grid grid-cols-3 gap-6 max-w-[320px] mx-auto mt-8">
            {keys.map((key, i) => {
                if (key === '') return <div key={i}></div>;
                if (key === 'back') return <button key={i} onClick={onDelete} className="w-16 h-16 rounded-full flex items-center justify-center hover:bg-surface-container-high transition-colors"><span className="material-symbols-outlined text-2xl">backspace</span></button>;
                return <button key={i} onClick={() => onInput(key)} className="w-16 h-16 rounded-full bg-surface-container text-2xl font-black border border-outline-variant hover:bg-surface-container-high active:scale-90 transition-all shadow-sm">{key}</button>;
            })}
        </div>
    );
};

export const M3ChoiceCard: React.FC<{ icon: string; label: string; onClick: () => void; selected: boolean; className?: string }> = ({ icon, label, onClick, selected, className = '' }) => (
    <button type="button" onClick={onClick} className={`flex flex-col items-center justify-center p-6 rounded-[32px] border-2 transition-all gap-2 min-w-[120px] ${selected ? 'border-primary bg-primary-container text-on-primary-container shadow-xl scale-[1.05]' : 'border-outline-variant bg-surface hover:border-outline' } ${className}`}>
        <span className="material-symbols-outlined text-3xl">{icon}</span>
        <span className="text-[11px] font-black uppercase tracking-widest">{label}</span>
    </button>
);

// --- CATEGORY CARD ---
export const CategoryCard: React.FC<{ id: string; label: string; icon: string; color: string; isSelected: boolean; onClick: () => void; description?: string }> = ({ label, icon, color, isSelected, onClick, description }) => (
    <div onClick={onClick} className={`flex flex-col items-center gap-3 p-4 rounded-2xl border-2 transition-all cursor-pointer ${isSelected ? 'border-primary bg-primary-container' : 'border-outline-variant bg-surface hover:border-outline'}`}>
        <div className="w-12 h-12 rounded-full flex items-center justify-center" style={{ backgroundColor: isSelected ? 'transparent' : color + '20', color: isSelected ? 'inherit' : color }}>
            <span className="material-symbols-outlined text-2xl">{icon}</span>
        </div>
        <span className="m3-label-medium font-bold text-center">{label}</span>
        {description && <p className="text-[10px] text-on-surface-variant text-center opacity-60 leading-tight">{description}</p>}
    </div>
);

export const EmptyState: React.FC<{ title: string; description: string; icon?: string }> = ({ title, description, icon = 'inbox' }) => (
    <div className="flex flex-col items-center justify-center p-12 text-center bg-surface-container-low rounded-[40px] border border-dashed border-outline-variant">
        <div className="w-20 h-20 rounded-full bg-surface-container-high flex items-center justify-center mb-6 text-on-surface-variant/40"><span className="material-symbols-outlined text-5xl">{icon}</span></div>
        <h3 className="m3-headline-small text-on-surface font-bold">{title}</h3>
        <p className="m3-body-large text-on-surface-variant max-w-sm mx-auto mt-2">{description}</p>
    </div>
);

// --- MANUAL & USE CASE ---
export const ManualSection: React.FC<{ title: string; icon: string; colorClass?: string; children: React.ReactNode; defaultOpen?: boolean }> = ({ title, icon, colorClass = '', children, defaultOpen = false }) => (
    <details className="m3-expansion-panel group border-none bg-surface-container-low rounded-2xl mb-3 overflow-hidden" open={defaultOpen}>
        <summary className="m3-expansion-summary !px-4 !py-4 hover:bg-surface-container-high cursor-pointer list-none flex justify-between items-center">
            <div className={`flex items-center gap-4 ${colorClass}`}>
                <div className="p-2 rounded-xl bg-surface-container-highest">
                    <span className="material-symbols-outlined text-2xl">{icon}</span>
                </div>
                <h3 className="m3-title-medium font-bold">{title}</h3>
            </div>
            <span className="material-symbols-outlined group-open:rotate-180 transition-transform">expand_more</span>
        </summary>
        <div className="m3-expansion-content !px-4 !pb-4 space-y-4">{children}</div>
    </details>
);

export const UseCaseCard: React.FC<{ scenario: string; steps: string[]; tip?: string }> = ({ scenario, steps, tip }) => (
    <div className="bg-surface p-5 rounded-2xl border border-outline-variant shadow-sm">
        <p className="m3-label-small text-primary mb-2 uppercase font-bold tracking-widest">Scenario</p>
        <p className="m3-title-medium font-bold mb-3">"{scenario}"</p>
        <ol className="list-decimal pl-5 space-y-2 text-sm text-on-surface-variant">
            {steps.map((step, i) => <li key={i} dangerouslySetInnerHTML={{ __html: step }}></li>)}
        </ol>
        {tip && <div className="mt-4 flex gap-3 p-3 bg-secondary-container/30 rounded-xl text-xs"><span className="material-symbols-outlined text-secondary">lightbulb</span><span className="font-medium">{tip}</span></div>}
    </div>
);
