import React, { useState } from 'react';

interface ShareModalProps {
    title: string;
    text: string;
    onClose: () => void;
}

const ShareModal: React.FC<ShareModalProps> = ({ title, text, onClose }) => {
    const [copyStatus, setCopyStatus] = useState<'idle' | 'copied'>('idle');

    const handleSimpleShare = async () => {
        if (navigator.share) {
            try {
                await navigator.share({
                    title: title,
                    text: text,
                });
                onClose();
            } catch (error) {
                console.error('Error sharing:', error);
            }
        } else {
            alert('La condivisione nativa non è supportata su questo browser.');
        }
    };
    
    const handleCopyFormatted = () => {
        const markdownText = text.split('\n').map(line => {
            const trimmed = line.trim();
            if (trimmed.startsWith('- ') || trimmed.startsWith('* ')) {
                return trimmed;
            }
            return `- ${trimmed}`;
        }).join('\n');

        navigator.clipboard.writeText(markdownText).then(() => {
            setCopyStatus('copied');
            setTimeout(() => {
                setCopyStatus('idle');
                onClose();
            }, 1500);
        }).catch(err => {
            console.error('Failed to copy markdown text: ', err);
            alert('Impossibile copiare il testo formattato.');
        });
    };

    return (
        <div className="dialog-backdrop" onClick={onClose}>
            <div className="dialog-container w-full max-w-sm" onClick={e => e.stopPropagation()}>
                <div className="dialog-header">
                    <h2 className="m3-headline-small">Condividi</h2>
                    <button onClick={onClose} className="icon-button rounded-lg hover:shadow-md transition-all">
                        <span className="material-symbols-outlined">close</span>
                    </button>
                </div>
                <div className="dialog-content flex flex-col gap-3">
                    <button onClick={handleSimpleShare} className="flex items-center gap-3 p-4 rounded-xl bg-surface-container hover:bg-surface-container-high transition-colors text-left">
                        <div className="w-10 h-10 rounded-full bg-secondary-container text-on-secondary-container flex items-center justify-center">
                             <span className="material-symbols-outlined">share</span>
                        </div>
                        <div>
                            <p className="m3-label-large">Condividi via...</p>
                            <p className="m3-body-small text-on-surface-variant">WhatsApp, Email, Drive</p>
                        </div>
                    </button>
                    
                    <button onClick={handleCopyFormatted} className="flex items-center gap-3 p-4 rounded-xl bg-surface-container hover:bg-surface-container-high transition-colors text-left">
                        <div className="w-10 h-10 rounded-full bg-tertiary-container text-on-tertiary-container flex items-center justify-center">
                             <span className="material-symbols-outlined">{copyStatus === 'copied' ? 'check' : 'content_paste'}</span>
                        </div>
                        <div>
                            <p className="m3-label-large">{copyStatus === 'copied' ? 'Copiato!' : 'Copia Formattato'}</p>
                            <p className="m3-body-small text-on-surface-variant">Per registro elettronico o Padlet</p>
                        </div>
                    </button>
                </div>
            </div>
        </div>
    );
};

export default ShareModal;
