

import React, { useMemo } from 'react';
import { Studente, Valutazione, ValutazioneCompetenza, TimetableSettings, Competenza } from '../types';
import { calculatePerformance } from '../utils/evaluationUtils';
import BarChart from './charts/BarChart';
import Avatar from './Avatar';

interface StudentInterviewModalProps {
    student: Studente;
    evaluations: Valutazione[];
    competencyEvaluations: ValutazioneCompetenza[];
    settings: TimetableSettings;
    onClose: () => void;
}

const StudentInterviewModal: React.FC<StudentInterviewModalProps> = ({ student, evaluations, competencyEvaluations, settings, onClose }) => {
    const performance = useMemo(() => calculatePerformance(student.id, 'Complessivo', evaluations), [student.id, evaluations]);
    
    // Group evaluations by subject
    const subjectAverages = useMemo(() => {
        const groups: Record<string, number[]> = {};
        evaluations.forEach(ev => {
            if (!groups[ev.materia]) groups[ev.materia] = [];
            const val = parseFloat(ev.voto);
            if (!isNaN(val)) groups[ev.materia].push(val);
        });
        
        return Object.entries(groups).map(([materia, voti]) => ({
            label: materia,
            value: parseFloat((voti.reduce((a, b) => a + b, 0) / voti.length).toFixed(1))
        }));
    }, [evaluations]);

    // Recent competencies
    const recentCompetencies = useMemo(() => {
        return settings.competenze.map(comp => {
            const latestEval = competencyEvaluations
                .filter(e => e.competenzaId === comp.id)
                .sort((a, b) => new Date(b.data).getTime() - new Date(a.data).getTime())[0];
            
            if (!latestEval) return null;
            const level = comp.livelli.find(l => l.id === latestEval.livelloId);
            return { name: comp.nome, level: level?.nome, desc: level?.descrizione, date: latestEval.data };
        }).filter(Boolean);
    }, [competencyEvaluations, settings.competenze]);

    return (
        <div className="dialog-backdrop"> {/* Use standard backdrop */}
            <div className="dialog-container w-full max-w-5xl h-[90vh]"> {/* Use standard container, enforce max-w and max-h */}
                {/* Privacy Header - integrated into dialog-header */}
                <div className="dialog-header bg-primary text-on-primary shadow-md">
                    <div className="flex items-center gap-4">
                        <Avatar name={student.nome} surname={student.cognome} size="large" className="bg-on-primary text-primary" />
                        <div>
                            <h1 className="m3-headline-medium truncate">{student.cognome} {student.nome}</h1>
                            <p className="text-on-primary/80">Modalità Colloquio - Classe {student.classe}</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="icon-button text-on-primary hover:bg-on-primary/10">
                        <span className="material-symbols-outlined mr-2">close</span>
                        <span className="hidden md:inline">Chiudi Vista</span>
                    </button>
                </div>

                <div className="dialog-content flex-grow overflow-y-auto p-6 bg-surface-container-low">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        
                        {/* Left Column: Performance */}
                        <div className="space-y-6">
                            <div className="card shadow-md"> {/* Use standard card */}
                                <h2 className="m3-title-large mb-4 flex items-center gap-2">
                                    <span className="material-symbols-outlined text-primary">monitoring</span>
                                    Andamento Didattico
                                </h2>
                                <div className="flex items-center gap-6 mb-6">
                                    <div className="card p-4 rounded-xl flex-1"> {/* Use standard card, smaller padding */}
                                        <span className="block text-sm text-on-surface-variant uppercase tracking-wider">Media Generale</span>
                                        <span className={`text-4xl font-bold ${parseFloat(performance.grade || '0') < 6 ? 'text-error' : 'text-primary'}`}>
                                            {performance.grade || '-'}
                                        </span>
                                    </div>
                                    <div className="card p-4 rounded-xl flex-1"> {/* Use standard card, smaller padding */}
                                        <span className="block text-sm text-on-surface-variant uppercase tracking-wider">Trend</span>
                                        <div className="flex items-center justify-center gap-1 mt-1">
                                            <span className={`material-symbols-outlined text-3xl ${performance.trend === 'up' ? 'text-tertiary' : performance.trend === 'down' ? 'text-error' : 'text-outline'}`}>
                                                {performance.trend === 'up' ? 'trending_up' : performance.trend === 'down' ? 'trending_down' : 'trending_flat'}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                                
                                <h3 className="m3-title-medium mb-2">Media per Materia</h3>
                                <BarChart data={subjectAverages} color="var(--sys-primary)" horizontal />
                            </div>

                            <div className="card shadow-md"> {/* Use standard card */}
                                <h2 className="m3-title-large mb-4 flex items-center gap-2">
                                    <span className="material-symbols-outlined text-secondary">history</span>
                                    Ultime Valutazioni
                                </h2>
                                <div className="space-y-2">
                                    {evaluations.sort((a,b) => new Date(b.data).getTime() - new Date(a.data).getTime()).slice(0, 5).map(ev => (
                                        <div key={ev.id} className="flex justify-between items-center p-3 bg-surface-container-lowest rounded-lg border border-outline-variant">
                                            <div>
                                                <p className="font-bold">{ev.materia}</p>
                                                <p className="text-xs text-on-surface-variant">{new Date(ev.data).toLocaleDateString()} - {ev.tipo}</p>
                                            </div>
                                            <span className={`text-lg font-bold px-3 py-1 rounded ${parseFloat(ev.voto) < 6 ? 'bg-error-container text-on-error-container' : 'bg-primary-container text-on-primary-container'}`}>
                                                {ev.voto}
                                            </span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>

                        {/* Right Column: Competencies & Notes */}
                        <div className="space-y-6">
                            <div className="card shadow-md bg-tertiary-container text-on-tertiary-container"> {/* Use standard card */}
                                <h2 className="m3-title-large mb-2 flex items-center gap-2">
                                    <span className="material-symbols-outlined">psychology</span>
                                    Competenze Trasversali
                                </h2>
                                <p className="opacity-80 mb-4">Livelli raggiunti nelle competenze chiave.</p>
                                <div className="space-y-3">
                                    {recentCompetencies.length > 0 ? recentCompetencies.map((c, i) => (
                                        <div key={i} className="bg-surface/50 p-3 rounded-xl backdrop-blur-sm">
                                            <p className="text-sm font-bold opacity-70 uppercase">{c?.name}</p>
                                            <div className="flex justify-between items-baseline mt-1">
                                                <span className="text-xl font-bold">{c?.level}</span>
                                                <span className="text-xs opacity-60">{new Date(c?.date!).toLocaleDateString()}</span>
                                            </div>
                                            <p className="text-sm mt-1">{c?.desc}</p>
                                        </div>
                                    )) : <p className="italic opacity-70">Nessuna competenza valutata recentemente.</p>}
                                </div>
                            </div>

                            <div className="card shadow-md bg-secondary-container text-on-secondary-container"> {/* Use standard card */}
                                <h2 className="m3-title-large mb-2 flex items-center gap-2">
                                    <span className="material-symbols-outlined">lightbulb</span>
                                    Punti di Attenzione
                                </h2>
                                <p className="m3-body-medium">
                                    {parseFloat(performance.grade || '0') >= 7 
                                        ? "Lo studente dimostra un buon impegno e partecipazione. Continuare a stimolare l'interesse."
                                        : parseFloat(performance.grade || '0') >= 6
                                            ? "Rendimento sufficiente ma con margini di miglioramento. Necessario consolidare il metodo di studio."
                                            : "È necessario un intervento di recupero mirato per colmare le lacune evidenziate."}
                                </p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default StudentInterviewModal;
