
import React, { useEffect, useRef, useState } from 'react';
import Logo from './Logo.tsx';
import { UserProfile } from '../types.ts';
import { DEFAULT_TIMETABLE_SETTINGS } from '../constants.ts';
import { TextField } from './M3Components.tsx';

const SignInScreen: React.FC<{ onSignInSuccess: (profile: UserProfile) => void }> = ({ onSignInSuccess }) => {
  const [manualName, setManualName] = useState('');
  const signInButtonRef = useRef<HTMLDivElement>(null);

  const handleManualSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if(manualName.trim()) {
      onSignInSuccess({ id: 'local-' + Date.now(), displayName: manualName.trim() });
    }
  };

  useEffect(() => {
    const initGSI = () => {
      if (typeof google === 'undefined') return;
      
      const clientId = DEFAULT_TIMETABLE_SETTINGS.googleClientId;
      
      google.accounts.id.initialize({
        client_id: clientId,
        callback: (res: any) => {
          if (res.credential) {
            const payload = JSON.parse(atob(res.credential.split('.')[1]));
            onSignInSuccess({ 
              id: payload.sub, 
              displayName: payload.name, 
              email: payload.email, 
              photoURL: payload.picture 
            });
          }
        }
      });

      if (signInButtonRef.current) {
        google.accounts.id.renderButton(signInButtonRef.current, { 
          theme: 'outline', size: 'large', shape: 'pill', width: 300 
        });
      }
    };

    const script = document.createElement('script');
    script.src = 'https://accounts.google.com/gsi/client';
    script.async = true;
    script.defer = true;
    script.onload = initGSI;
    document.head.appendChild(script);
  }, [onSignInSuccess]);

  return (
    <div className="m3-auth-screen relative flex items-center justify-center min-h-screen bg-aura-gradient overflow-hidden">
      {/* Ornaments */}
      <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-primary/10 blur-[120px] rounded-full animate-pulse"></div>
      <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-tertiary/10 blur-[120px] rounded-full animate-pulse delay-1000"></div>

      <div className="m3-auth-card w-full max-w-md p-10 md:p-14 bg-glass-bg backdrop-blur-3xl rounded-[48px] shadow-3xl border border-white/40 text-center z-10 animate-in fade-in zoom-in-95 duration-700">
        <div className="flex justify-center mb-12 transform scale-150 origin-center drop-shadow-2xl">
            <Logo />
        </div>
        
        <div className="space-y-2 mb-12">
          <h1 className="m3-headline-medium font-black tracking-tighter text-on-surface leading-none">Bentornato</h1>
          <p className="m3-body-large font-bold opacity-50 uppercase tracking-[0.3em] text-[10px]">Ecosistema Didattico Intelligente</p>
        </div>

        <div className="flex justify-center mb-12 transition-transform hover:scale-105" ref={signInButtonRef}></div>

        <div className="relative mb-12">
          <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-outline-variant/50"></div></div>
          <div className="relative flex justify-center text-[10px] font-black uppercase tracking-[0.5em] text-on-surface-variant">
              <span className="bg-surface px-6 py-1 rounded-full border border-outline-variant/30 shadow-sm">O Accesso Locale</span>
          </div>
        </div>

        <form onSubmit={handleManualSubmit} className="space-y-8">
          <TextField 
            label="Identità del Docente"
            placeholder="Nome e Cognome..."
            value={manualName}
            onChange={e => setManualName(e.target.value)}
            required
            autoComplete="name"
          />
          
          <button 
            type="submit" 
            className="button button-filled w-full !h-16 !rounded-[32px] font-black text-lg shadow-2xl hover:scale-[1.03] active:scale-95 transition-all flex items-center justify-center gap-4"
          >
            Accedi ora
            <span className="material-symbols-outlined font-black text-2xl">arrow_forward</span>
          </button>
        </form>
        
        <footer className="mt-14 flex flex-col items-center gap-4">
           <p className="text-[10px] font-black opacity-30 uppercase tracking-[0.4em] flex items-center justify-center gap-2">
              <span className="material-symbols-outlined text-sm">security</span>
              Dati Crittografati Localmente
           </p>
        </footer>
      </div>
    </div>
  );
};

export default SignInScreen;
