
import React, { useRef, useEffect } from 'react';
import { Notifica, View } from '../types';

interface NotificationsPopoverProps {
    notifiche: Notifica[];
    onClose: () => void;
    onMarkAsRead: (notificationId: string) => void;
    onMarkAllAsRead: () => void;
    onNavigate: (view: View) => void;
    onOpenCircularAnalysis: (url: string, title: string) => void;
}

const NotificationsPopover: React.FC<NotificationsPopoverProps> = ({
    notifiche,
    onClose,
    onMarkAsRead,
    onMarkAllAsRead,
    onNavigate,
    onOpenCircularAnalysis,
}) => {
    const popoverRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (popoverRef.current && !popoverRef.current.contains(event.target as Node)) {
                onClose();
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [onClose]);

    const unreadCount = notifiche.filter(n => !n.letta).length;
    const sortedNotifiche = [...notifiche].sort((a, b) => new Date(b.data).getTime() - new Date(a.data).getTime());

    const handleItemClick = (notifica: Notifica) => {
        onMarkAsRead(notifica.id);
        if (notifica.type === 'reminder') {
            onNavigate('calendario');
        }
    };

    return (
        <div ref={popoverRef} className="m3-popup-menu header-notifications-popover">
            <div className="popup-header flex justify-between items-center">
                <h3 className="m3-title-medium pl-2">Notifiche</h3>
                <div className="flex items-center gap-2">
                    {unreadCount > 0 && (
                        <button onClick={onMarkAllAsRead} className="text-primary text-xs font-bold px-3 py-1 rounded-full bg-primary-container hover:bg-primary/20 transition-colors">
                            Segna lette
                        </button>
                    )}
                    <button onClick={onClose} className="icon-button !w-8 !h-8" aria-label="Chiudi notifiche">
                        <span className="material-symbols-outlined text-sm">close</span>
                    </button>
                </div>
            </div>
            
            {sortedNotifiche.length > 0 ? (
                <div className="flex flex-col gap-1 p-1">
                    {sortedNotifiche.map(notifica => (
                        <div
                            key={notifica.id}
                            className={`m3-menu-item !items-start !p-3 !rounded-xl ${!notifica.letta ? 'bg-primary-container/30' : ''}`}
                            onClick={() => handleItemClick(notifica)}
                        >
                            <div className={`mt-1 p-1.5 rounded-full ${!notifica.letta ? 'bg-primary text-on-primary' : 'bg-surface-container-high text-on-surface-variant'}`}>
                                <span className="material-symbols-outlined text-sm">
                                    {notifica.type === 'circular' ? 'feed' : 'notifications'}
                                </span>
                            </div>
                            <div className="flex-grow min-w-0">
                                <p className={`m3-body-medium truncate ${!notifica.letta ? 'font-bold text-on-surface' : 'text-on-surface-variant'}`}>{notifica.titolo}</p>
                                <p className="m3-body-small text-on-surface-variant opacity-80 line-clamp-2">{notifica.messaggio}</p>
                                {notifica.type === 'circular' && (
                                    <div className="flex gap-2 mt-2">
                                        <button onClick={(e) => { e.stopPropagation(); onOpenCircularAnalysis(notifica.payload.url, notifica.payload.title); onClose(); }} className="button button-tonal !h-7 !px-3 !text-[10px]">
                                            <span className="material-symbols-outlined text-xs mr-1">auto_awesome</span> Analizza
                                        </button>
                                    </div>
                                )}
                            </div>
                            {!notifica.letta && <div className="w-2 h-2 rounded-full bg-primary mt-2"></div>}
                        </div>
                    ))}
                </div>
            ) : (
                <div className="p-8 text-center text-on-surface-variant opacity-60 flex flex-col items-center">
                    <span className="material-symbols-outlined text-4xl mb-2">notifications_off</span>
                    <p className="m3-body-medium">Nessuna notifica</p>
                </div>
            )}
        </div>
    );
};

export default NotificationsPopover;
