
import React from 'react';
import { SyncConflictData } from '../types';

interface SyncConflictModalProps {
    data: SyncConflictData;
    onRestore: () => void;
    onIgnore: () => void;
}

const SyncConflictModal: React.FC<SyncConflictModalProps> = ({ data, onRestore, onIgnore }) => {
    // Determina quale è più recente
    const isRemoteNewer = data.remoteTime > data.localTime;
    const remoteDate = new Date(data.remoteTime);
    const localDate = data.localTime ? new Date(data.localTime) : null;

    return (
        <div className="dialog-backdrop" style={{ zIndex: 3000 }}>
            <div className="dialog-container max-w-md w-full bg-surface-container-high border-l-4 border-primary">
                <div className="dialog-header">
                    <h2 className="m3-headline-small flex items-center gap-2 text-primary">
                        <span className="material-symbols-outlined">cloud_sync</span>
                        Conflitto Sincronizzazione
                    </h2>
                </div>
                
                <div className="dialog-content space-y-4 pt-2">
                    <p className="m3-body-large text-on-surface">
                        Abbiamo trovato un backup più recente su Google Drive rispetto ai dati su questo dispositivo.
                    </p>
                    
                    <div className="flex flex-col gap-3">
                        {/* LOCAL CARD */}
                        <div className={`p-4 rounded-xl border flex justify-between items-center ${!isRemoteNewer ? 'bg-secondary-container border-secondary' : 'bg-surface border-outline-variant opacity-70'}`}>
                            <div>
                                <p className="text-xs font-bold uppercase tracking-wider mb-1">Dati Locali (Attuali)</p>
                                <p className="font-mono text-sm font-bold">
                                    {localDate ? localDate.toLocaleString() : 'Nessun dato'}
                                </p>
                            </div>
                            {!isRemoteNewer && <span className="text-xs bg-surface text-on-surface px-2 py-1 rounded-full font-bold shadow-sm">Più Recente</span>}
                        </div>

                        {/* DIRECTION ARROW */}
                        <div className="flex justify-center -my-2 relative z-10">
                            <div className="bg-surface-container-high rounded-full p-1 border border-outline-variant">
                                <span className="material-symbols-outlined text-primary">arrow_downward</span>
                            </div>
                        </div>

                        {/* REMOTE CARD */}
                        <div className={`p-4 rounded-xl border flex justify-between items-center ${isRemoteNewer ? 'bg-primary-container border-primary shadow-sm' : 'bg-surface border-outline-variant'}`}>
                            <div>
                                <p className="text-xs font-bold uppercase tracking-wider mb-1 flex items-center gap-1">
                                    <span className="material-symbols-outlined text-sm">cloud</span>
                                    Cloud (Drive)
                                </p>
                                <p className="font-mono text-sm font-bold text-primary">
                                    {remoteDate.toLocaleString()}
                                </p>
                            </div>
                            {isRemoteNewer && <span className="text-xs bg-primary text-on-primary px-2 py-1 rounded-full font-bold shadow-sm">Consigliato</span>}
                        </div>
                    </div>

                    <p className="m3-body-small text-on-surface-variant text-center px-4">
                        Vuoi scaricare i dati dal Cloud e aggiornare questo dispositivo? 
                        <br/>
                        <span className="text-error">I dati locali verranno sovrascritti.</span>
                    </p>
                </div>

                <div className="dialog-footer gap-3">
                    <button 
                        onClick={onIgnore} 
                        className="button button-text"
                    >
                        Matieni Locali
                    </button>
                    <button 
                        onClick={onRestore} 
                        className="button button-filled w-full justify-center"
                    >
                        <span className="material-symbols-outlined mr-2">download</span>
                        Sincronizza dal Cloud
                    </button>
                </div>
            </div>
        </div>
    );
};

export default SyncConflictModal;
