
import React, { useState, useMemo } from 'react';
import { Studente, Prova, Valutazione, ValutazioneCompetenza, TimetableSettings } from '../types';
import { RATING_OPTIONS } from '../constants';

interface UnifiedEvaluationModalProps {
    student: Studente;
    prova: Prova;
    settings: TimetableSettings;
    existingGrade: Valutazione | undefined;
    existingCompetencyEvals: ValutazioneCompetenza[];
    onClose: () => void;
    onSave: (data: {
        grade: string;
        competencyEvals: Record<string, string>; // competenzaId -> livelloId
    }) => void;
}

const getTestTypeIcon = (tipo: string) => {
    switch(tipo) {
        case 'Scritto': return 'edit_note';
        case 'Orale': return 'record_voice_over';
        case 'Pratico': return 'build';
        case 'Test': return 'quiz';
        default: return 'assignment';
    }
};

const UnifiedEvaluationModal: React.FC<UnifiedEvaluationModalProps> = ({
    student,
    prova,
    settings,
    existingGrade,
    existingCompetencyEvals,
    onClose,
    onSave,
}) => {
    const [grade, setGrade] = useState(existingGrade?.voto || '');
    const [selectedLevels, setSelectedLevels] = useState<Record<string, string>>(() => {
        return existingCompetencyEvals.reduce((acc, curr) => {
            acc[curr.competenzaId] = curr.livelloId;
            return acc;
        }, {} as Record<string, string>);
    });

    const relevantCompetencies = useMemo(() => {
        return settings.competenze.filter(c =>
            !c.disciplines || c.disciplines.length === 0 || c.disciplines.includes(prova.materia)
        );
    }, [settings.competenze, prova.materia]);

    const handleLevelChange = (competenzaId: string, livelloId: string) => {
        setSelectedLevels(prev => ({
            ...prev,
            [competenzaId]: livelloId
        }));
    };
    
    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSave({ grade, competencyEvals: selectedLevels });
    };

    return (
        <div className="dialog-backdrop">
            <form onSubmit={handleSubmit} className="dialog-container w-full max-w-3xl">
                <div className="dialog-header">
                    <div>
                        <div className="flex items-center gap-2 mb-1">
                             <span className="material-symbols-outlined text-primary">{getTestTypeIcon(prova.tipo)}</span>
                             <h2 className="m3-headline-medium">Valutazione {prova.tipo}</h2>
                        </div>
                        <p className="m3-body-medium text-on-surface-variant">
                            {student.cognome} {student.nome} - {prova.titolo} ({prova.materia})
                        </p>
                    </div>
                    <button type="button" onClick={onClose} className="icon-button">
                        <span className="material-symbols-outlined">close</span>
                    </button>
                </div>
                <div className="dialog-content space-y-6 pt-4">
                    <div className="bg-surface-container-low p-4 rounded-xl">
                        <h3 className="m3-title-medium mb-2">Voto Numerico</h3>
                        <select value={grade} onChange={e => setGrade(e.target.value)} className="expressive-select w-full max-w-sm px-4">
                            <option value="">Nessun Voto</option>
                            {RATING_OPTIONS.map(o => <option key={o} value={o}>{o}</option>)}
                        </select>
                    </div>

                    <div>
                        <h3 className="m3-title-medium mb-2">Competenze Valutate</h3>
                        {relevantCompetencies.length > 0 ? (
                            <div className="space-y-4 max-h-[45vh] overflow-y-auto pr-2">
                                {relevantCompetencies.map(competenza => (
                                    <div key={competenza.id} className="p-4 border rounded-xl border-outline-variant bg-surface-container">
                                        <h4 className="m3-title-small mb-2 text-primary">{competenza.nome}</h4>
                                        <div className="space-y-2">
                                            {competenza.livelli.map(level => (
                                                <label key={level.id} className="flex items-start cursor-pointer p-2 rounded-lg hover:bg-surface-container-high transition-colors">
                                                    <input
                                                        type="radio"
                                                        name={`competenza-${competenza.id}`}
                                                        value={level.id}
                                                        checked={selectedLevels[competenza.id] === level.id}
                                                        onChange={() => handleLevelChange(competenza.id, level.id)}
                                                        className="mr-3 mt-1 accent-primary"
                                                    />
                                                    <div>
                                                        <span className="m3-body-large font-medium">{level.nome}</span>
                                                        <p className="m3-body-small text-on-surface-variant opacity-80">{level.descrizione}</p>
                                                    </div>
                                                </label>
                                            ))}
                                        </div>
                                         <button type="button" onClick={() => setSelectedLevels(prev => { const {[competenza.id]: _, ...rest} = prev; return rest; })} className="button button-text !text-xs !h-auto !py-1 !px-2 mt-2 text-on-surface-variant">
                                            Azzera selezione
                                        </button>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <p className="m3-body-medium text-on-surface-variant italic p-4 text-center">Nessuna competenza associata alla materia "{prova.materia}".</p>
                        )}
                    </div>
                </div>
                <div className="dialog-footer">
                    <button type="button" onClick={onClose} className="button button-text">Annulla</button>
                    <button type="submit" className="button button-filled">Salva Valutazione</button>
                </div>
            </form>
        </div>
    );
};

export default UnifiedEvaluationModal;
